<?php $reconciliation=$case['proposal']['reconciliation']??null;if($reconciliation):?>
<section class="card"><h2>Linked Money Review</h2><p>The actual transfer, deposit and wallet-credit amounts stay unchanged. These linked allocation adjustments post with the receipt correction, once.</p>
<?php if($reconciliation['funding']):?><h3>Existing Supporting Receipts</h3><?php foreach($reconciliation['funding'] as $method=>$funding):?><p><?=access_h(ucfirst($method))?> · Receipt #<?=(int)$funding['payment_id']?> · <?=access_h(cc_money($funding['amount']))?></p><?php endforeach;endif?>
<?php if($reconciliation['cash_views']):?><h3>Cash Funding Before &amp; After</h3><div class="cc-scroll"><table class="cc-funding"><thead><tr><th>Recorded Movement</th><th>Actual Amount</th><th>Before</th><th>After</th></tr></thead><tbody><?php foreach($reconciliation['cash_views'] as $view):?><tr><td data-label="Recorded Movement">#<?=(int)$view['event_id']?> · <?=access_h(cc_movement_label($view['kind']))?></td><td data-label="Actual Amount"><?=access_h(cc_money($view['amount_minor']))?> · Unchanged</td><td data-label="Before"><?php foreach($view['before']['allocations']??[] as $receipt=>$amount):?><div>Receipt #<?=access_h($receipt)?> · <?=access_h(cc_money($amount))?></div><?php endforeach?></td><td data-label="After"><?php foreach($view['data']['allocations']??[] as $receipt=>$amount):?><div>Receipt #<?=access_h($receipt)?> · <?=access_h(cc_money($amount))?></div><?php endforeach?></td></tr><?php endforeach?></tbody></table></div><?php endif?>
<?php if($reconciliation['cash_changes']):?><h3>Recorded Cash Responsibility</h3><?php foreach($reconciliation['cash_changes'] as $change):?><p>Receipt #<?=(int)$change['payment_id']?></p><?php foreach(array_unique(array_merge(array_keys($change['before']),array_keys($change['after']))) as $staff):?><p><?=access_h(cc_person((int)$staff))?> · <?=access_h(cc_money($change['before'][$staff]??0))?> → <?=access_h(cc_money($change['after'][$staff]??0))?></p><?php endforeach;endforeach;endif?>
<?php if($wallet=$reconciliation['wallet']):?><h3>Existing Wallet Proof Allocation</h3><p>Proof #<?=(int)$wallet['proof_event_id']?> · <?=access_h($wallet['reference'])?></p><p><?=access_h(cc_money($wallet['amount']))?> is allocated from Receipt #<?=(int)$wallet['from']?> to the existing Receipt #<?=(int)$wallet['to']?>. The original merchant credit and reference claim remain; no additional credit is recorded.</p><?php endif?>
<p>Actual Money Moved: GHS 0.00. Original records, earlier proposals and closed snapshots remain retained.</p></section>
<?php endif?>
